func (t transaction_Do) FindByPage(offset int, limit int) (result []*model.Transaction_, count int64, err error) {
	result, err = t.Offset(offset).Limit(limit).Find()
	if err != nil {
		return
	}

	if size := len(result); 0 < limit && 0 < size && size < limit {
		count = int64(size + offset)
		return
	}

	count, err = t.Offset(-1).Limit(-1).Count()
	return
}

func (t transaction_Do) ScanByPage(result interface{}, offset int, limit int) (count int64, err error) {
	count, err = t.Count()
	if err != nil {
		return
	}

	err = t.Offset(offset).Limit(limit).Scan(result)
	return
}

func (t transaction_Do) Scan(result interface{}) (err error) {
	return t.DO.Scan(result)
}

func (t transaction_Do) Delete(models ...*model.Transaction_) (result gen.ResultInfo, err error) {
	return t.DO.Delete(models)
}

func (t *transaction_Do) withDO(do gen.Dao) *transaction_Do {
	t.DO = *do.(*gen.DO)
	return t
}
